BEGIN;
CREATE OR REPLACE FUNCTION research_private.permissions() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path='' AS $f$
SELECT ARRAY['view_study','edit_study','manage_questionnaires','view_aggregate_results','view_pseudonymized_data','view_identifiable_data','view_document_content','export_data','manage_participants','contact_participants','manage_researchers','manage_consent','view_audit_log','view_approved_findings','download_approved_findings','propose_analysis','view_analysis_results','comment_on_findings','view_approved_pseudonymized_data','export_approved_dataset','view_study_progress','view_approved_contributions']::text[] $f$;

CREATE TABLE research_private.partnership_partners(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),actor_ref text NOT NULL UNIQUE,revision integer NOT NULL DEFAULT 0,profile jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE research_private.partnership_records(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL REFERENCES research_private.studies(id),partner_id uuid NOT NULL REFERENCES research_private.partnership_partners(id),kind text NOT NULL,status text NOT NULL DEFAULT 'draft',revision integer NOT NULL DEFAULT 0,head_version_id uuid,approved_version_id uuid,published_version_id uuid,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(study_id,partner_id,id));
CREATE TABLE research_private.partnership_versions(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL,partner_id uuid NOT NULL,record_id uuid NOT NULL,number integer NOT NULL,data jsonb NOT NULL,content_hash text NOT NULL,proposed_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,submitted_at timestamptz,UNIQUE(study_id,partner_id,record_id,id),UNIQUE(record_id,number),FOREIGN KEY(study_id,partner_id,record_id) REFERENCES research_private.partnership_records(study_id,partner_id,id));
ALTER TABLE research_private.partnership_records ADD FOREIGN KEY(study_id,partner_id,id,head_version_id) REFERENCES research_private.partnership_versions(study_id,partner_id,record_id,id),ADD FOREIGN KEY(study_id,partner_id,id,approved_version_id) REFERENCES research_private.partnership_versions(study_id,partner_id,record_id,id),ADD FOREIGN KEY(study_id,partner_id,id,published_version_id) REFERENCES research_private.partnership_versions(study_id,partner_id,record_id,id);
CREATE TABLE research_private.partnership_reviews(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL,partner_id uuid NOT NULL,record_id uuid NOT NULL,version_id uuid NOT NULL,decision text NOT NULL,note text NOT NULL DEFAULT '',approved_terms jsonb,cancellation_agreement_version_id uuid,reviewed_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(study_id,partner_id,record_id,version_id) REFERENCES research_private.partnership_versions(study_id,partner_id,record_id,id));
CREATE TABLE research_private.partnership_publications(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL,partner_id uuid NOT NULL,record_id uuid NOT NULL,version_id uuid NOT NULL,viewer_partner_ids uuid[] NOT NULL,download_partner_ids uuid[] NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,withdrawn_at timestamptz,FOREIGN KEY(study_id,partner_id,record_id,version_id) REFERENCES research_private.partnership_versions(study_id,partner_id,record_id,id),CHECK(download_partner_ids<@viewer_partner_ids));
CREATE TABLE research_private.partnership_comments(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL,partner_id uuid NOT NULL,record_id uuid NOT NULL,version_id uuid NOT NULL,text text NOT NULL,author_id uuid REFERENCES research_private.partnership_partners(id),author_label text NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(study_id,partner_id,record_id,version_id) REFERENCES research_private.partnership_versions(study_id,partner_id,record_id,id));
CREATE TABLE research_private.partnership_approvals(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL,partner_id uuid NOT NULL,record_id uuid NOT NULL,version_id uuid NOT NULL,document_hash text NOT NULL,party text NOT NULL CHECK(party IN ('owner','partner')),ip_explanation_version_id uuid NOT NULL REFERENCES research_private.partnership_versions(id),created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(record_id,version_id,party),FOREIGN KEY(study_id,partner_id,record_id,version_id) REFERENCES research_private.partnership_versions(study_id,partner_id,record_id,id));
CREATE TABLE research_private.partnership_invitations(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL REFERENCES research_private.studies(id),partner_id uuid NOT NULL REFERENCES research_private.partnership_partners(id),revision integer NOT NULL DEFAULT 0,digest text NOT NULL UNIQUE,preset text NOT NULL,permissions text[] NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,accepted_at timestamptz,revoked_at timestamptz);
CREATE TABLE research_private.partnership_documents(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL REFERENCES research_private.studies(id),partner_id uuid NOT NULL REFERENCES research_private.partnership_partners(id),record_id uuid,filename text NOT NULL,media_type text NOT NULL,size integer NOT NULL CHECK(size BETWEEN 1 AND 8388608),sha256 text NOT NULL CHECK(sha256~'^[a-f0-9]{64}$'),content_ciphertext jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(study_id,partner_id,record_id) REFERENCES research_private.partnership_records(study_id,partner_id,id));
CREATE TABLE research_private.partnership_snapshots(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL REFERENCES research_private.studies(id),partner_id uuid NOT NULL REFERENCES research_private.partnership_partners(id),consent_version_id uuid NOT NULL,participant_ids uuid[] NOT NULL,response_ids uuid[] NOT NULL,variables text[] NOT NULL,source_rows jsonb NOT NULL,questionnaire_version_ids uuid[] NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(study_id,consent_version_id) REFERENCES research_private.form_versions(study_id,id));
CREATE TABLE research_private.partnership_signings(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL,partner_id uuid NOT NULL,record_id uuid NOT NULL,version_id uuid NOT NULL,document_hash text NOT NULL,provider_session_id text NOT NULL UNIQUE,provider_document_hash text NOT NULL CHECK(provider_document_hash~'^[a-f0-9]{64}$'),provider_state_ciphertext jsonb NOT NULL,authority_policy_hash text NOT NULL,state text NOT NULL DEFAULT 'awaiting_signers',provider_checked_at timestamptz,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at timestamptz,FOREIGN KEY(study_id,partner_id,record_id,version_id) REFERENCES research_private.partnership_versions(study_id,partner_id,record_id,id));
ALTER TABLE research_private.partnership_documents ADD COLUMN signing_id uuid REFERENCES research_private.partnership_signings(id),ADD COLUMN evidence_purpose text CHECK(evidence_purpose IN ('final','certificate')),ADD UNIQUE(signing_id,evidence_purpose);
CREATE TABLE research_private.partnership_executions(id uuid PRIMARY KEY DEFAULT pg_catalog.gen_random_uuid(),study_id uuid NOT NULL,partner_id uuid NOT NULL,record_id uuid NOT NULL,version_id uuid NOT NULL,signing_id uuid NOT NULL UNIQUE REFERENCES research_private.partnership_signings(id),document_hash text NOT NULL,provider_event_id text NOT NULL UNIQUE,final_document_id uuid NOT NULL REFERENCES research_private.partnership_documents(id),final_document_hash text NOT NULL,audit_document_id uuid NOT NULL REFERENCES research_private.partnership_documents(id),verified_signers jsonb NOT NULL,completed_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(study_id,partner_id,record_id,version_id) REFERENCES research_private.partnership_versions(study_id,partner_id,record_id,id));
CREATE TABLE research_private.partnership_receipts(actor_ref text NOT NULL,scope text NOT NULL,action text NOT NULL,request_id uuid NOT NULL,payload_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(actor_ref,scope,action,request_id));

CREATE FUNCTION research_private.partnership_scope(sid uuid,pid uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.current_setting('research.owner',true)='true' OR pg_catalog.current_setting('research.signing',true)='true' OR (sid::text=pg_catalog.current_setting('research.study',true) AND pid::text=pg_catalog.current_setting('research.partner',true)) $f$;
DO $tables$ DECLARE t text; BEGIN
 FOR t IN SELECT tablename FROM pg_catalog.pg_tables WHERE schemaname='research_private' AND tablename LIKE 'partnership_%' LOOP
  EXECUTE pg_catalog.format('ALTER TABLE research_private.%I OWNER TO research_table_owner',t);
  EXECUTE pg_catalog.format('ALTER TABLE research_private.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE pg_catalog.format('ALTER TABLE research_private.%I FORCE ROW LEVEL SECURITY',t);
  EXECUTE pg_catalog.format('REVOKE ALL ON research_private.%I FROM PUBLIC,anon,authenticated,service_role',t);
  EXECUTE pg_catalog.format('GRANT SELECT,INSERT,UPDATE,DELETE ON research_private.%I TO research_worker',t);
  IF t='partnership_partners' THEN EXECUTE 'CREATE POLICY partnership_scope ON research_private.partnership_partners TO research_worker USING(pg_catalog.current_setting(''research.owner'',true)=''true'' OR pg_catalog.current_setting(''research.signing'',true)=''true'' OR actor_ref=pg_catalog.current_setting(''research.actor'',true) OR id::text=pg_catalog.current_setting(''research.partner'',true)) WITH CHECK(pg_catalog.current_setting(''research.owner'',true)=''true'' OR actor_ref=pg_catalog.current_setting(''research.actor'',true))';
  ELSIF t='partnership_receipts' THEN EXECUTE 'CREATE POLICY partnership_scope ON research_private.partnership_receipts TO research_worker USING(actor_ref=pg_catalog.current_setting(''research.actor'',true)) WITH CHECK(actor_ref=pg_catalog.current_setting(''research.actor'',true))';
  ELSIF t='partnership_invitations' THEN EXECUTE 'CREATE POLICY partnership_scope ON research_private.partnership_invitations TO research_worker USING(research_private.partnership_scope(study_id,partner_id) OR digest=pg_catalog.current_setting(''research.partner_invite'',true)) WITH CHECK(research_private.partnership_scope(study_id,partner_id))';
  ELSE EXECUTE pg_catalog.format('CREATE POLICY partnership_scope ON research_private.%I TO research_worker USING(research_private.partnership_scope(study_id,partner_id)) WITH CHECK(research_private.partnership_scope(study_id,partner_id))',t); END IF;
  IF t IN ('partnership_versions','partnership_reviews','partnership_comments','partnership_approvals','partnership_documents','partnership_snapshots','partnership_executions','partnership_receipts') THEN EXECUTE pg_catalog.format('CREATE TRIGGER partnership_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON research_private.%I FOR EACH STATEMENT EXECUTE FUNCTION research_private.immutable()',t); END IF;
 END LOOP;
END $tables$;

-- A released record can appear inside the viewer's own folder. No sibling profile,
-- document, snapshot, private version or source-folder aggregate is covered by this policy.
CREATE POLICY partnership_released ON research_private.partnership_publications TO research_worker USING(study_id::text=pg_catalog.current_setting('research.study',true) AND withdrawn_at IS NULL AND EXISTS(SELECT 1 FROM research_private.partnership_partners own WHERE own.actor_ref=pg_catalog.current_setting('research.actor',true) AND own.id=ANY(viewer_partner_ids)));
CREATE POLICY partnership_released ON research_private.partnership_records TO research_worker USING(study_id::text=pg_catalog.current_setting('research.study',true) AND EXISTS(SELECT 1 FROM research_private.partnership_publications pub JOIN research_private.partnership_partners own ON own.id=ANY(pub.viewer_partner_ids) WHERE pub.record_id=partnership_records.id AND pub.version_id=partnership_records.published_version_id AND pub.withdrawn_at IS NULL AND own.actor_ref=pg_catalog.current_setting('research.actor',true)));
CREATE POLICY partnership_released ON research_private.partnership_versions TO research_worker USING(study_id::text=pg_catalog.current_setting('research.study',true) AND EXISTS(SELECT 1 FROM research_private.partnership_publications pub JOIN research_private.partnership_partners own ON own.id=ANY(pub.viewer_partner_ids) WHERE pub.version_id=partnership_versions.id AND pub.withdrawn_at IS NULL AND own.actor_ref=pg_catalog.current_setting('research.actor',true)));

CREATE FUNCTION research_private.partnership_canonical(d jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $f$ DECLARE result text; BEGIN
 IF pg_catalog.jsonb_typeof(d)='object' THEN SELECT '{'||COALESCE(pg_catalog.string_agg(pg_catalog.to_jsonb(x.key)::text||':'||research_private.partnership_canonical(x.value),',' ORDER BY x.key COLLATE "C"),'')||'}' INTO result FROM pg_catalog.jsonb_each(d) x;
 ELSIF pg_catalog.jsonb_typeof(d)='array' THEN SELECT '['||COALESCE(pg_catalog.string_agg(research_private.partnership_canonical(x.value),',' ORDER BY x.ordinality),'')||']' INTO result FROM pg_catalog.jsonb_array_elements(d) WITH ORDINALITY x;
 ELSE result:=d::text; END IF; RETURN result;
END $f$;
CREATE FUNCTION research_private.partnership_hash(d jsonb) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $f$ SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(research_private.partnership_canonical(d),'UTF8')),'hex') $f$;

CREATE FUNCTION research_private.partnership_snapshot_current(sid uuid,pid uuid,snapshot_id uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $f$
 SELECT EXISTS(SELECT 1 FROM research_private.partnership_snapshots snap JOIN research_private.studies s ON s.id=snap.study_id WHERE snap.id=snapshot_id AND snap.study_id=sid AND snap.partner_id=pid AND s.config->>'consentVersionId'=snap.consent_version_id::text AND NOT EXISTS(SELECT 1 FROM pg_catalog.unnest(snap.participant_ids) p(id) LEFT JOIN research_private.participants current ON current.id=p.id AND current.study_id=sid WHERE current.id IS NULL OR current.status<>'enrolled' OR NOT current.verified OR current.consents->>'participate' IS DISTINCT FROM 'true' OR current.consents->>'surveys' IS DISTINCT FROM 'true' OR current.consent_version_id<>snap.consent_version_id) AND NOT EXISTS(SELECT 1 FROM pg_catalog.unnest(snap.response_ids) wanted(id) WHERE NOT EXISTS(SELECT 1 FROM research_private.responses r WHERE r.id=wanted.id AND r.study_id=sid))) $f$;
CREATE POLICY partnership_released ON research_private.partnership_snapshots TO research_worker USING(study_id::text=pg_catalog.current_setting('research.study',true) AND EXISTS(SELECT 1 FROM research_private.partnership_publications pub JOIN research_private.partnership_versions ver ON ver.id=pub.version_id JOIN research_private.partnership_partners own ON own.id=ANY(pub.viewer_partner_ids) WHERE pub.withdrawn_at IS NULL AND own.actor_ref=pg_catalog.current_setting('research.actor',true) AND ver.study_id=partnership_snapshots.study_id AND ver.partner_id=partnership_snapshots.partner_id AND ver.data->>'sourceSnapshotId'=partnership_snapshots.id::text));
CREATE FUNCTION research_private.partnership_view_permission(kind text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $f$ SELECT CASE kind WHEN 'analysis_result' THEN 'view_analysis_results' WHEN 'contribution' THEN 'view_approved_contributions' ELSE 'view_approved_findings' END $f$;
CREATE FUNCTION research_private.partnership_released(r research_private.partnership_records,viewer uuid,download boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $f$
 SELECT EXISTS(SELECT 1 FROM research_private.partnership_publications pub WHERE pub.record_id=r.id AND pub.version_id=r.published_version_id AND pub.withdrawn_at IS NULL AND viewer=ANY(pub.viewer_partner_ids) AND pg_catalog.current_setting('research.permissions',true)::jsonb ? research_private.partnership_view_permission(r.kind) AND (NOT download OR viewer=ANY(pub.download_partner_ids) AND pg_catalog.current_setting('research.permissions',true)::jsonb ? 'download_approved_findings')) $f$;
CREATE FUNCTION research_private.partnership_version_current(v research_private.partnership_versions) RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT NOT(v.data ? 'sourceSnapshotId') OR research_private.partnership_snapshot_current(v.study_id,v.partner_id,(v.data->>'sourceSnapshotId')::uuid) $f$;
CREATE FUNCTION research_private.partnership_document_current(d research_private.partnership_documents) RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $f$
 SELECT NOT EXISTS(SELECT 1 FROM research_private.partnership_records rec JOIN research_private.partnership_versions ver ON ver.record_id=rec.id WHERE rec.study_id=d.study_id AND rec.partner_id=d.partner_id AND (rec.id=d.record_id AND ver.id=rec.head_version_id OR COALESCE(ver.data->'resultDocumentIds','[]') ? d.id::text OR COALESCE(ver.data->'supportingDocumentIds','[]') ? d.id::text) AND NOT research_private.partnership_version_current(ver)) $f$;
CREATE FUNCTION research_private.partnership_ref(sid uuid,pid uuid,target text,reference_id uuid,complete boolean) RETURNS void LANGUAGE plpgsql SET search_path='' AS $f$ DECLARE found_ref boolean:=false; BEGIN
 IF target IN ('instrument','consent') THEN SELECT EXISTS(SELECT 1 FROM research_private.form_versions v JOIN research_private.form_publications p ON p.study_id=v.study_id AND p.version_id=v.id WHERE v.id=reference_id AND v.study_id=sid AND v.kind=target) INTO found_ref;
 ELSIF target='snapshot' THEN found_ref:=research_private.partnership_snapshot_current(sid,pid,reference_id);
 ELSIF target='document' THEN SELECT EXISTS(SELECT 1 FROM research_private.partnership_documents d WHERE d.id=reference_id AND d.study_id=sid AND d.partner_id=pid) INTO found_ref;
 ELSIF target IN ('agreement_template_version','agreement_version') THEN SELECT EXISTS(SELECT 1 FROM research_private.partnership_versions v JOIN research_private.partnership_records r ON r.id=v.record_id WHERE v.id=reference_id AND v.study_id=sid AND v.partner_id=pid AND r.kind=CASE target WHEN 'agreement_version' THEN 'agreement' ELSE 'agreement_template' END AND (NOT complete OR CASE target WHEN 'agreement_version' THEN r.status='executed' AND EXISTS(SELECT 1 FROM research_private.partnership_executions e WHERE e.version_id=v.id) ELSE r.status='approved' AND r.approved_version_id=v.id AND r.head_version_id=v.id END)) INTO found_ref;
 ELSE SELECT EXISTS(SELECT 1 FROM research_private.partnership_records r WHERE r.id=reference_id AND r.study_id=sid AND r.partner_id=pid AND (target='record' OR r.kind=target) AND (NOT complete OR target NOT IN ('application','contribution','budget','analysis_result') OR r.status IN ('approved','completed','published'))) INTO found_ref; END IF;
 IF NOT found_ref THEN PERFORM research_private.fail('not_found'); END IF;
END $f$;
CREATE FUNCTION research_private.partnership_fields(fields jsonb,d jsonb,sid uuid,pid uuid,complete boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE def jsonb; val jsonb; cell jsonb; k text; str text; typ text; BEGIN
 IF pg_catalog.jsonb_typeof(d) IS DISTINCT FROM 'object' THEN PERFORM research_private.fail('invalid'); END IF;
 FOR k IN SELECT pg_catalog.jsonb_object_keys(d) LOOP IF NOT EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(fields) f WHERE f->>'id'=k) THEN PERFORM research_private.fail('invalid'); END IF; END LOOP;
 FOR def IN SELECT * FROM pg_catalog.jsonb_array_elements(fields) LOOP
  val:=d->(def->>'id');typ:=def->>'type';
  IF complete AND def->>'required'='true' AND (val IS NULL OR val='null'::jsonb OR val='[]'::jsonb OR (pg_catalog.jsonb_typeof(val)='string' AND pg_catalog.btrim(val#>>'{}')='')) THEN PERFORM research_private.fail('invalid'); END IF;
  IF val IS NULL THEN CONTINUE; END IF;
  str:=val#>>'{}';
  IF val='""'::jsonb AND typ IN ('text','email','date','id','enum','money') THEN CONTINUE; END IF;
  IF typ IN ('text','email','date','id','enum','money') AND pg_catalog.jsonb_typeof(val)<>'string' THEN PERFORM research_private.fail('invalid'); END IF;
  IF typ='text' THEN IF pg_catalog.length(str)>COALESCE((def->>'maxLength')::integer,20000) THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF typ='email' THEN IF pg_catalog.length(str)>254 OR str!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF typ='date' THEN IF str!~'^\d{4}-\d{2}-\d{2}$' OR pg_catalog.to_char(str::date,'YYYY-MM-DD')<>str THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF typ='id' THEN IF str!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF typ='money' THEN IF str!~'^(0|[1-9][0-9]{0,11})\.[0-9]{2}$' THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF typ='integer' THEN IF pg_catalog.jsonb_typeof(val)<>'number' OR str!~'^[0-9]+$' OR str::numeric>9007199254740991 THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF typ='boolean' THEN IF pg_catalog.jsonb_typeof(val)<>'boolean' THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF typ='enum' THEN IF NOT (def->'choices' ? str) THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF typ IN ('tags','rows') THEN
   IF pg_catalog.jsonb_typeof(val)<>'array' OR pg_catalog.jsonb_array_length(val)>200 THEN PERFORM research_private.fail('invalid'); END IF;
   IF typ='tags' AND (SELECT pg_catalog.count(*)<>pg_catalog.count(DISTINCT x) FROM pg_catalog.jsonb_array_elements(val) x) THEN PERFORM research_private.fail('invalid'); END IF;
   FOR cell IN SELECT * FROM pg_catalog.jsonb_array_elements(val) LOOP
    IF typ='rows' THEN PERFORM research_private.partnership_fields(def->'fields',cell,sid,pid,complete);
    ELSE IF pg_catalog.jsonb_typeof(cell)<>'string' OR pg_catalog.btrim(cell#>>'{}')='' OR pg_catalog.length(cell#>>'{}')>500 OR (def ? 'choices' AND NOT(def->'choices' ? (cell#>>'{}'))) OR (def->>'itemType'='id' AND (cell#>>'{}')!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$') THEN PERFORM research_private.fail('invalid'); END IF;
     IF def ? 'reference' THEN PERFORM research_private.partnership_ref(sid,pid,def->>'reference',(cell#>>'{}')::uuid,complete); END IF;
    END IF;
   END LOOP;
  ELSE PERFORM research_private.fail('invalid'); END IF;
  IF typ='id' AND def ? 'reference' THEN PERFORM research_private.partnership_ref(sid,pid,def->>'reference',str::uuid,complete); END IF;
 END LOOP;
END $f$;
CREATE FUNCTION research_private.partnership_validate(kind text,d jsonb,sid uuid,pid uuid,complete boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE fields jsonb:=research_private.partnership_contract()#>ARRAY['schemas',kind,'fields']; section_id text; text_value text; placeholder text; required_id text; template jsonb; BEGIN
 IF fields IS NULL THEN PERFORM research_private.fail('invalid'); END IF;
 PERFORM research_private.partnership_fields(fields,d,sid,pid,complete);
 IF (d->>'startDate'>d->>'endDate') OR (d->>'effectiveDate'>d->>'terminationDate') THEN PERFORM research_private.fail('invalid'); END IF;
 IF kind='analysis_request' THEN
  IF complete AND d->>'operation'='comparison' AND pg_catalog.btrim(COALESCE(d->>'groupingVariable',''))='' THEN PERFORM research_private.fail('invalid'); END IF;
  IF pg_catalog.btrim(COALESCE(d->>'groupingVariable',''))<>'' AND NOT EXISTS(SELECT 1 FROM research_private.form_versions f JOIN research_private.form_publications fp ON fp.study_id=f.study_id AND fp.version_id=f.id JOIN research_private.studies st ON st.id=f.study_id CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(f.definition->'items') q WHERE f.study_id=sid AND f.kind='instrument' AND st.config->'instrumentVersionIds' ? f.id::text AND q->>'id'=d->>'groupingVariable' AND q->>'type'='choice') THEN PERFORM research_private.fail('invalid'); END IF;
 END IF;
 IF kind='agreement_template' THEN
  IF (SELECT pg_catalog.count(*)<>pg_catalog.count(DISTINCT x->>'sectionId') FROM pg_catalog.jsonb_array_elements(COALESCE(d->'sectionClauses','[]')) x) OR (complete AND pg_catalog.jsonb_array_length(COALESCE(d->'sectionClauses','[]'))<>12) THEN PERFORM research_private.fail('invalid'); END IF;
  FOR required_id IN SELECT pg_catalog.jsonb_array_elements_text(COALESCE(d->'requiredFieldIds','[]')) LOOP IF NOT EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(research_private.partnership_contract()#>'{schemas,agreement,fields}') f WHERE f->>'id'=required_id) THEN PERFORM research_private.fail('invalid'); END IF; END LOOP;
  FOR text_value IN SELECT d->>'ipExplanation' UNION ALL SELECT d->>'mutualIPClause' UNION ALL SELECT x->>'text' FROM pg_catalog.jsonb_array_elements(COALESCE(d->'sectionClauses','[]')) x LOOP
   FOR placeholder IN SELECT (pg_catalog.regexp_matches(text_value,'\{\{([A-Za-z][A-Za-z0-9]*)\}\}','g'))[1] LOOP IF NOT EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(research_private.partnership_contract()#>'{schemas,agreement,fields}') f WHERE f->>'id'=placeholder) THEN PERFORM research_private.fail('invalid'); END IF; END LOOP;
   text_value:=pg_catalog.regexp_replace(text_value,'\{\{([A-Za-z][A-Za-z0-9]*)\}\}','','g'); IF text_value LIKE '%{{%' OR text_value LIKE '%}}%' THEN PERFORM research_private.fail('invalid'); END IF;
  END LOOP;
 ELSIF kind='agreement' AND complete THEN
  IF d->>'templateVersionId' IS DISTINCT FROM d->>'ipExplanationVersionId' THEN PERFORM research_private.fail('invalid'); END IF;
  SELECT v.data INTO template FROM research_private.partnership_versions v WHERE v.id=(d->>'templateVersionId')::uuid;
  FOR required_id IN SELECT pg_catalog.jsonb_array_elements_text(COALESCE(template->'requiredFieldIds','[]')) UNION SELECT (pg_catalog.regexp_matches(t,'\{\{([A-Za-z][A-Za-z0-9]*)\}\}','g'))[1] FROM (SELECT template->>'ipExplanation' t UNION ALL SELECT template->>'mutualIPClause' UNION ALL SELECT x->>'text' FROM pg_catalog.jsonb_array_elements(template->'sectionClauses') x) texts LOOP IF NOT(d ? required_id) OR d->required_id='[]' OR d->required_id='""' OR (pg_catalog.jsonb_typeof(d->required_id)='string' AND pg_catalog.btrim(d->>required_id)='') THEN PERFORM research_private.fail('invalid'); END IF; END LOOP;
 END IF;
END $f$;
CREATE FUNCTION research_private.partnership_partner(p research_private.partnership_partners) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_build_object('id',p.id,'revision',p.revision,'profile',p.profile,'createdAt',p.created_at,'updatedAt',p.updated_at) $f$;
CREATE FUNCTION research_private.partnership_record(r research_private.partnership_records) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_build_object('id',r.id,'studyId',r.study_id,'partnerId',r.partner_id,'kind',r.kind,'status',r.status,'revision',r.revision,'headVersionId',r.head_version_id,'approvedVersionId',r.approved_version_id,'publishedVersionId',r.published_version_id,'createdAt',r.created_at,'updatedAt',r.updated_at,'binding',r.kind='agreement' AND EXISTS(SELECT 1 FROM research_private.partnership_executions e WHERE e.version_id=r.head_version_id) OR r.kind='obligation' AND r.status<>'draft' AND r.status<>'under_review' AND EXISTS(SELECT 1 FROM research_private.partnership_versions v JOIN research_private.partnership_executions e ON e.version_id=(v.data->>'sourceAgreementVersionId')::uuid WHERE v.id=r.head_version_id)) || CASE WHEN r.kind='obligation' THEN COALESCE((SELECT pg_catalog.jsonb_build_object('sourceAgreementStatus',ar.status,'sourceAgreementVersionId',e.version_id,'sourceAgreementHash',e.document_hash,'providerVerification','verified','ownerReviewed',EXISTS(SELECT 1 FROM research_private.partnership_reviews rv WHERE rv.record_id=r.id AND rv.decision='approved')) FROM research_private.partnership_versions current_version JOIN research_private.partnership_executions e ON e.version_id=(current_version.data->>'sourceAgreementVersionId')::uuid JOIN research_private.partnership_records ar ON ar.id=e.record_id WHERE current_version.id=r.head_version_id),'{}'::jsonb) ELSE '{}'::jsonb END $f$;
CREATE FUNCTION research_private.partnership_version(v research_private.partnership_versions) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_build_object('id',v.id,'recordId',v.record_id,'studyId',v.study_id,'partnerId',v.partner_id,'number',v.number,'data',v.data,'contentHash',v.content_hash,'createdAt',v.created_at,'proposedBy',v.proposed_by,'submittedAt',(SELECT pg_catalog.min(x.created_at) FROM research_private.partnership_reviews x WHERE x.version_id=v.id AND x.decision='submitted')) $f$;
CREATE FUNCTION research_private.partnership_review(v research_private.partnership_reviews) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_build_object('id',v.id,'recordId',v.record_id,'versionId',v.version_id,'decision',v.decision,'note',v.note,'reviewedAt',v.created_at,'reviewedBy',v.reviewed_by,'approvedTerms',v.approved_terms,'cancellationAgreementVersionId',v.cancellation_agreement_version_id) $f$;
CREATE FUNCTION research_private.partnership_approval(v research_private.partnership_approvals) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_build_object('id',v.id,'recordId',v.record_id,'versionId',v.version_id,'documentHash',v.document_hash,'party',v.party,'ipExplanationVersionId',v.ip_explanation_version_id,'ipReadAcknowledgedAt',v.created_at,'approvedAt',v.created_at) $f$;
CREATE FUNCTION research_private.partnership_document(v research_private.partnership_documents) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_build_object('id',v.id,'studyId',v.study_id,'partnerId',v.partner_id,'recordId',v.record_id,'filename',v.filename,'mediaType',v.media_type,'size',v.size,'sha256',v.sha256,'createdAt',v.created_at) $f$;
CREATE FUNCTION research_private.partnership_invitation(v research_private.partnership_invitations) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_build_object('id',v.id,'studyId',v.study_id,'partnerId',v.partner_id,'revision',v.revision,'status',CASE WHEN v.revoked_at IS NOT NULL THEN 'revoked' WHEN v.accepted_at IS NOT NULL THEN 'accepted' WHEN v.expires_at<=CURRENT_TIMESTAMP THEN 'expired' ELSE 'pending' END,'expiresAt',v.expires_at,'createdAt',v.created_at,'acceptedAt',v.accepted_at,'revokedAt',v.revoked_at,'preset',v.preset,'permissions',v.permissions) $f$;
CREATE FUNCTION research_private.partnership_signing(v research_private.partnership_signings) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_build_object('id',v.id,'recordId',v.record_id,'versionId',v.version_id,'documentHash',v.document_hash,'state',CASE WHEN v.expires_at<=CURRENT_TIMESTAMP AND v.state<>'completed' THEN 'expired' ELSE v.state END,'configured',true,'embeddedUrl',NULL,'expiresAt',v.expires_at,'completedAt',v.completed_at) $f$;
CREATE FUNCTION research_private.partnership_cipher(d jsonb) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path='' AS $f$ SELECT pg_catalog.jsonb_typeof(d)='object' AND d->'v'='1' AND (SELECT pg_catalog.count(*)=4 FROM pg_catalog.jsonb_object_keys(d)) AND pg_catalog.jsonb_typeof(d->'iv')='string' AND d->>'iv'~'^[A-Za-z0-9+/]{16}$' AND pg_catalog.jsonb_typeof(d->'tag')='string' AND d->>'tag'~'^[A-Za-z0-9+/]{22}==$' AND pg_catalog.jsonb_typeof(d->'data')='string' AND pg_catalog.length(d->>'data') BETWEEN 4 AND 16000000 AND d->>'data'~'^[A-Za-z0-9+/]+={0,2}$' $f$;

CREATE FUNCTION research_private.partnership_live_member(sid uuid,subject_actor text) RETURNS boolean LANGUAGE plpgsql SET search_path='' AS $f$
BEGIN
 PERFORM 1 FROM research_private.memberships m WHERE m.study_id=sid AND m.actor_ref=subject_actor AND 'view_study'=ANY(m.permissions) FOR SHARE;
 IF NOT FOUND THEN RETURN false; END IF;
 PERFORM research_private.live_individual(pg_catalog.substr(subject_actor,6));
 RETURN true;
EXCEPTION WHEN SQLSTATE 'P0001' THEN
 IF SQLERRM='invalid' THEN RETURN false; END IF;
 RAISE;
END $f$;

CREATE FUNCTION research_private.partnership_workspace(s research_private.studies,p research_private.partnership_partners,kind_filter text DEFAULT NULL,status_filter text DEFAULT NULL,query_filter text DEFAULT NULL) RETURNS jsonb LANGUAGE sql VOLATILE SET search_path='' AS $f$
 WITH visible AS (SELECT r.*,v.data,v.id AS visible_version_id,v.number AS visible_number,v.created_at AS visible_created_at,(r.partner_id=p.id AND (pg_catalog.current_setting('research.owner',true)='true' OR r.kind<>'analysis_result')) AS private_view FROM research_private.partnership_records r JOIN research_private.partnership_versions v ON v.id=CASE WHEN r.partner_id=p.id AND (pg_catalog.current_setting('research.owner',true)='true' OR r.kind<>'analysis_result') THEN r.head_version_id ELSE r.published_version_id END WHERE r.study_id=s.id AND (r.partner_id=p.id AND (pg_catalog.current_setting('research.owner',true)='true' OR r.kind<>'analysis_result') OR pg_catalog.current_setting('research.owner',true)<>'true' AND research_private.partnership_released(r,p.id)) AND research_private.partnership_version_current(v) AND (kind_filter IS NULL OR r.kind=kind_filter) AND (status_filter IS NULL OR r.status=status_filter) AND (query_filter IS NULL OR pg_catalog.strpos(pg_catalog.lower(v.data->>'title'),pg_catalog.lower(query_filter))>0))
 SELECT pg_catalog.jsonb_build_object('studyId',s.id,'partnerId',p.id,'studyTitle',s.config->>'title','partnerName',p.profile->>'fullName','partnershipActive',research_private.partnership_live_member(s.id,p.actor_ref) AND s.status='active' AND s.config#>>'{approvals,status}'='approved' AND EXISTS(SELECT 1 FROM research_private.form_publications fp WHERE fp.study_id=s.id AND fp.version_id=(s.config->>'consentVersionId')::uuid) AND EXISTS(SELECT 1 FROM research_private.partnership_records ar JOIN research_private.partnership_executions ex ON ex.version_id=ar.head_version_id WHERE ar.study_id=s.id AND ar.partner_id=p.id AND ar.status='executed'),'recordCounts',COALESCE((SELECT pg_catalog.jsonb_object_agg(kind,n) FROM (SELECT kind,pg_catalog.count(*) n FROM visible GROUP BY kind) x),'{}'),'pendingCount',(SELECT pg_catalog.count(*) FROM visible WHERE status IN ('submitted','under_review','owner_review')),'deadlines',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('recordId',id,'date',COALESCE(data->>'dueDate',data->>'endDate',data->>'terminationDate'))) FROM visible WHERE COALESCE(data->>'dueDate',data->>'endDate',data->>'terminationDate') IS NOT NULL),'[]'),'records',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',id,'partnerId',partner_id,'kind',kind,'status',CASE WHEN private_view THEN status WHEN kind='contribution' AND status='completed' THEN 'completed' WHEN kind='contribution' THEN 'approved' ELSE 'published' END,'revision',CASE WHEN private_view THEN revision ELSE visible_number END,'title',data->>'title','updatedAt',CASE WHEN private_view THEN updated_at ELSE visible_created_at END,'headVersionId',visible_version_id) ORDER BY updated_at DESC,id) FROM visible),'[]'),'documents',COALESCE((SELECT pg_catalog.jsonb_agg(research_private.partnership_document(d)) FROM research_private.partnership_documents d WHERE d.study_id=s.id AND d.partner_id=p.id AND research_private.partnership_document_current(d) AND (pg_catalog.current_setting('research.owner',true)='true' OR NOT EXISTS(SELECT 1 FROM research_private.partnership_records ar JOIN research_private.partnership_versions av ON av.id=ar.head_version_id WHERE ar.study_id=s.id AND ar.partner_id=p.id AND ar.kind='analysis_result' AND (ar.id=d.record_id OR COALESCE(av.data->'resultDocumentIds','[]') ? d.id::text) AND NOT EXISTS(SELECT 1 FROM visible vis WHERE vis.id=ar.id AND COALESCE(vis.data->'resultDocumentIds','[]') ? d.id::text)))),'[]'),'snapshots',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',snap.id,'createdAt',snap.created_at,'consentProtocolVersionId',snap.consent_version_id,'questionnaireVersionIds',snap.questionnaire_version_ids)) FROM research_private.partnership_snapshots snap WHERE snap.study_id=s.id AND snap.partner_id=p.id AND research_private.partnership_snapshot_current(s.id,p.id,snap.id)),'[]')) $f$;

CREATE FUNCTION research_private.partnership_signing_auth(raw_token text) RETURNS jsonb LANGUAGE plpgsql SET search_path='' AS $f$ DECLARE parts text[]; secret text; body jsonb; expected text; BEGIN
 parts:=pg_catalog.string_to_array(raw_token,'.'); IF pg_catalog.array_length(parts,1)<>2 OR pg_catalog.length(raw_token)>12000 THEN PERFORM research_private.fail('unauthorized'); END IF;
 SELECT value->>'secret' INTO secret FROM public.access_settings WHERE key='token-secret' FOR SHARE;
 expected:=pg_catalog.translate(pg_catalog.rtrim(pg_catalog.encode(research_private.hmac(pg_catalog.convert_to(parts[1],'UTF8'),pg_catalog.convert_to(secret,'UTF8')),'base64'),'='),'+/','-_');
 IF secret IS NULL OR parts[2] IS DISTINCT FROM expected THEN PERFORM research_private.fail('unauthorized'); END IF;
 body:=pg_catalog.convert_from(pg_catalog.decode(pg_catalog.translate(parts[1],'-_','+/')||pg_catalog.repeat('=',(4-pg_catalog.length(parts[1])%4)%4),'base64'),'UTF8')::jsonb;
 IF body->>'k' IS DISTINCT FROM 'research_signing_worker' OR body->>'purpose' IS DISTINCT FROM 'research-signing' OR pg_catalog.jsonb_typeof(body->'exp') IS DISTINCT FROM 'number' OR (body->>'exp')::numeric<=pg_catalog.date_part('epoch',pg_catalog.clock_timestamp())*1000 OR (body->>'exp')::numeric>pg_catalog.date_part('epoch',pg_catalog.clock_timestamp())*1000+600000 THEN PERFORM research_private.fail('unauthorized'); END IF;
 RETURN '{"actor":"research-signing-worker","internal":true}'::jsonb;
 EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN PERFORM research_private.fail('unauthorized'); RETURN NULL;
END $f$;

CREATE FUNCTION research_private.partnership_extract(r research_private.partnership_records,v research_private.partnership_versions) RETURNS void LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE item jsonb; group_name text; position integer; obligation_data jsonb; obligation_id uuid; version_id uuid; BEGIN
 IF NOT EXISTS(SELECT 1 FROM research_private.partnership_executions e WHERE e.version_id=v.id) THEN PERFORM research_private.fail('not_found'); END IF;
 FOR group_name IN SELECT pg_catalog.unnest(ARRAY['sharedExpenses','professionalFees','milestones','ownerResponsibilities','partnerResponsibilities']) LOOP
  position:=0;
  FOR item IN SELECT x FROM pg_catalog.jsonb_array_elements(CASE WHEN group_name IN ('ownerResponsibilities','partnerResponsibilities') THEN CASE WHEN pg_catalog.btrim(COALESCE(v.data->>group_name,''))='' THEN '[]'::jsonb ELSE pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('description',v.data->>group_name,'party',CASE group_name WHEN 'ownerResponsibilities' THEN 'owner' ELSE 'partner' END)) END ELSE COALESCE(v.data->group_name,'[]') END) x LOOP
   position:=position+1;
   obligation_data:=pg_catalog.jsonb_build_object('title','התחייבות לחילוץ ובדיקת בעלת המערכת','sourceAgreementId',r.id,'sourceAgreementVersionId',v.id,'clauseReference',group_name||'['||position||']','party',COALESCE(item->>'party','owner'),'description',COALESCE(item->>'description',item->>'service',item->>'deliverable',item->>'title',''));
   IF item ? 'amount' THEN obligation_data:=obligation_data||pg_catalog.jsonb_build_object('amount',item->>'amount'); END IF;
   IF COALESCE(item->>'currency',v.data->>'currency') IS NOT NULL THEN obligation_data:=obligation_data||pg_catalog.jsonb_build_object('currency',COALESCE(item->>'currency',v.data->>'currency')); END IF;
   IF item ? 'dueDate' THEN obligation_data:=obligation_data||pg_catalog.jsonb_build_object('dueDate',item->>'dueDate'); END IF;
   INSERT INTO research_private.partnership_records(study_id,partner_id,kind) VALUES(r.study_id,r.partner_id,'obligation') RETURNING id INTO obligation_id;
   INSERT INTO research_private.partnership_versions(study_id,partner_id,record_id,number,data,content_hash,proposed_by) VALUES(r.study_id,r.partner_id,obligation_id,1,obligation_data,research_private.partnership_hash(obligation_data),'verified-execution') RETURNING id INTO version_id;
   UPDATE research_private.partnership_records SET head_version_id=version_id,revision=1 WHERE id=obligation_id;
  END LOOP;
 END LOOP;
END $f$;

CREATE FUNCTION research_private.partnership_request(action_name text,payload jsonb) RETURNS void LANGUAGE plpgsql SET search_path='' AS $f$
DECLARE spec record; value jsonb; typ text; item jsonb; BEGIN
 FOR spec IN SELECT x.key,x.value#>>'{}' AS description FROM pg_catalog.jsonb_each(research_private.partnership_contract()#>ARRAY['operations',action_name,'request']) x LOOP
  value:=payload->spec.key;typ:=pg_catalog.split_part(spec.description,' ',1);
  IF value IS NULL THEN
   IF pg_catalog.strpos(spec.description,'?')=0 AND NOT(action_name='workspaceDocumentPut' AND spec.key='contentBase64') AND NOT(action_name IN ('partnerInviteGet','partnerInviteAccept') AND spec.key='invite') THEN PERFORM research_private.fail('invalid'); END IF;
   CONTINUE;
  END IF;
  IF value='null'::jsonb THEN IF spec.key='expectedRevision' THEN CONTINUE; ELSE PERFORM research_private.fail('invalid'); END IF; END IF;
  IF typ LIKE 'uuid[]%' THEN
   IF pg_catalog.jsonb_typeof(value)<>'array' OR pg_catalog.jsonb_array_length(value)>200 THEN PERFORM research_private.fail('invalid'); END IF;
   FOR item IN SELECT * FROM pg_catalog.jsonb_array_elements(value) LOOP IF pg_catalog.jsonb_typeof(item)<>'string' OR item#>>'{}'!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN PERFORM research_private.fail('invalid'); END IF; END LOOP;
  ELSIF typ LIKE 'uuid%' THEN IF pg_catalog.jsonb_typeof(value)<>'string' OR value#>>'{}'!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF typ LIKE 'integer%' THEN IF pg_catalog.jsonb_typeof(value)<>'number' OR value#>>'{}'!~'^[0-9]+$' OR (value#>>'{}')::numeric>9007199254740991 THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF typ LIKE 'boolean%' OR typ='true' THEN IF pg_catalog.jsonb_typeof(value)<>'boolean' OR typ='true' AND value<>'true'::jsonb THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF spec.key IN ('data','profile','approvedTerms') THEN IF pg_catalog.jsonb_typeof(value)<>'object' THEN PERFORM research_private.fail('invalid'); END IF;
  ELSIF typ LIKE 'string[]%' THEN IF pg_catalog.jsonb_typeof(value)<>'array' OR pg_catalog.jsonb_array_length(value)>200 OR EXISTS(SELECT 1 FROM pg_catalog.jsonb_array_elements(value) a WHERE pg_catalog.jsonb_typeof(a)<>'string') THEN PERFORM research_private.fail('invalid'); END IF;
  ELSE IF pg_catalog.jsonb_typeof(value)<>'string' OR pg_catalog.length(value#>>'{}')>20000 THEN PERFORM research_private.fail('invalid'); END IF;
  END IF;
 END LOOP;
END $f$;

CREATE FUNCTION research_private.partnership_dispatch(p_token text,p_action text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $f$
#variable_conflict use_variable
DECLARE auth jsonb; actor text; owner_actor boolean; internal_actor boolean:=p_action IN ('signingPrepare','signingEvidencePut','signingEventContext','signingStateUpdate','signatureComplete'); sid uuid; pid uuid; self_id uuid; s research_private.studies; p research_private.partnership_partners; member research_private.memberships; r research_private.partnership_records; v research_private.partnership_versions; from_v research_private.partnership_versions; review research_private.partnership_reviews; approval research_private.partnership_approvals; invitation research_private.partnership_invitations; document research_private.partnership_documents; signing research_private.partnership_signings; snap research_private.partnership_snapshots; receipt research_private.partnership_receipts; result jsonb; items jsonb; partners jsonb; studies jsonb; workspaces jsonb; data jsonb; template jsonb; permitted text[]; viewers uuid[]; downloaders uuid[]; ids uuid[]; label text; key_name text; kind_name text; next_status text; hash text; scope_key text; request_id uuid; mutation boolean; author_actor boolean; can_view boolean; can_download boolean; party text; binding_source research_private.partnership_records; rr record; vars text[]; summary jsonb; provenance jsonb; created_version uuid; created_record uuid; consent_id uuid; expected integer; source_rows jsonb;
BEGIN
 PERFORM pg_catalog.set_config('research.actor','',true);PERFORM pg_catalog.set_config('research.owner','false',true);PERFORM pg_catalog.set_config('research.internal','false',true);PERFORM pg_catalog.set_config('research.signing','false',true);PERFORM pg_catalog.set_config('research.study','',true);PERFORM pg_catalog.set_config('research.partner','',true);PERFORM pg_catalog.set_config('research.partner_invite','',true);PERFORM pg_catalog.set_config('research.permissions','[]',true);
 IF pg_catalog.jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN PERFORM research_private.fail('invalid'); END IF;
 IF internal_actor THEN auth:=research_private.partnership_signing_auth(p_token); ELSE auth:=research_private.auth(p_token); IF COALESCE((auth->>'internal')::boolean,false) THEN PERFORM research_private.fail('unauthorized'); END IF; END IF;
 actor:=auth->>'actor';owner_actor:=COALESCE((auth->>'owner')::boolean,false);
 PERFORM pg_catalog.set_config('research.actor',actor,true);PERFORM pg_catalog.set_config('research.owner',owner_actor::text,true);PERFORM pg_catalog.set_config('research.signing',internal_actor::text,true);
 IF owner_actor THEN PERFORM pg_catalog.set_config('research.permissions',pg_catalog.to_jsonb(research_private.permissions())::text,true); END IF;
 IF NOT internal_actor AND research_private.partnership_contract()#>ARRAY['operations',p_action] IS NULL THEN PERFORM research_private.fail('invalid'); END IF;
 IF NOT internal_actor THEN PERFORM research_private.partnership_request(p_action,p_payload); END IF;
 FOR key_name IN SELECT pg_catalog.jsonb_object_keys(p_payload) LOOP
  IF key_name IN ('owner','actor','role','authority','executionStatus','providerEvidence','token','action') THEN PERFORM research_private.fail('invalid'); END IF;
  IF NOT internal_actor AND key_name<>'requestId' AND NOT(COALESCE(research_private.partnership_contract()#>ARRAY['operations',p_action,'request'],'{}') ? key_name) AND NOT(p_action IN ('partnerInviteCreate','partnerInviteGet','partnerInviteAccept') AND key_name='inviteDigest') AND NOT(p_action='workspaceDocumentPut' AND key_name IN ('contentCiphertext','size','sha256')) THEN PERFORM research_private.fail('invalid'); END IF;
 END LOOP;
 SELECT id INTO self_id FROM research_private.partnership_partners WHERE actor_ref=actor;
 mutation:=p_action<>'signingEventContext' AND NOT(research_private.partnership_contract()->'reads' ? p_action);
 IF mutation THEN request_id:=COALESCE((p_payload->>'requestId')::uuid,CASE WHEN p_action IN ('signingEvidencePut','signingStateUpdate','signatureComplete') THEN (p_payload->>'signingId')::uuid END); IF request_id IS NULL THEN PERFORM research_private.fail('invalid'); END IF; END IF;
 scope_key:=CASE WHEN p_action='partnerSave' AND NOT owner_actor THEN 'profile:'||actor ELSE COALESCE(p_payload->>'studyId','profile')||':'||COALESCE(p_payload->>'partnerId',p_payload->>'individualCode',self_id::text,actor) END||CASE WHEN p_action='signingEvidencePut' THEN ':'||COALESCE(p_payload->>'purpose','') WHEN p_action='signingStateUpdate' THEN ':'||COALESCE(p_payload->>'state','') ELSE '' END;
 IF mutation THEN
  hash:=research_private.partnership_hash(p_payload-'requestId'-'contentCiphertext'-'providerStateCiphertext'); PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(actor||scope_key||p_action||request_id,0));
  SELECT * INTO receipt FROM research_private.partnership_receipts x WHERE x.actor_ref=actor AND x.scope=scope_key AND x.action=p_action AND x.request_id=request_id AND p_action NOT IN ('signingRefresh','signingStateUpdate');
 END IF;
 IF p_action='signingEventContext' THEN
  SELECT * INTO signing FROM research_private.partnership_signings sg WHERE sg.provider_session_id=p_payload->>'providerSessionId' FOR UPDATE;
  IF signing.id IS NULL THEN PERFORM research_private.fail('not_found'); END IF;sid:=signing.study_id;pid:=signing.partner_id;
  PERFORM pg_catalog.set_config('research.study',sid::text,true);PERFORM pg_catalog.set_config('research.partner',pid::text,true);
  -- A verified provider event records an already issued session; app access revocation cannot erase its evidence.
  SELECT * INTO p FROM research_private.partnership_partners pp WHERE pp.id=pid;
  SELECT * INTO r FROM research_private.partnership_records rec WHERE rec.id=signing.record_id AND rec.head_version_id=signing.version_id AND rec.status IN ('signing','executed') FOR UPDATE;IF r.id IS NULL THEN PERFORM research_private.fail('not_found'); END IF;
